    !isNonnegativeSafeInteger(value.currentMatch) || value.currentMatch >= value.matches.length) return null;
  const matches: TournamentMatch[] = [];
  for (const [index, match] of value.matches.entries()) {
    if (!isJsonObject(match) || !hasExactKeys(match, ['boardCode', 'results']) ||
