      parseBoardCode(match.boardCode)?.size !== matchStage(names.names.length, index).size) return null;
    const results = readResults(match.results, matchStage(names.names.length, index).size);
    if (!results || (index < value.currentMatch && results.length !== 2) ||
      (index > value.currentMatch && results.length !== 0)) return null;
